function moveActor(actor,dir,distance){const p=actor.g.position,old=p.clone();let bounds;if(actor===player&&dungeonSession)bounds=[dungeonCore.x-24,dungeonCore.x+24,dungeonCore.z-24,dungeonCore.z+24];else if(actor===player&&currentHouse>=0)bounds=[997,1003,997,1003];else bounds=[-510,1500,-510,1500];const clamp=()=>{p.x=THREE.MathUtils.clamp(p.x,bounds[0],bounds[1]);p.z=THREE.MathUtils.clamp(p.z,bounds[2],bounds[3]);},blocked=()=>obstacles.some(o=>Math.hypot(p.x-o.x,p.z-o.z)<o.r);p.addScaledVector(dir,distance);clamp();if(blocked()){p.copy(old);p.x=THREE.MathUtils.clamp(old.x+dir.x*distance,bounds[0],bounds[1]);if(blocked())p.x=old.x;p.z=THREE.MathUtils.clamp(old.z+dir.z*distance,bounds[2],bounds[3]);if(blocked())p.z=old.z;if(blocked())p.copy(old);}}
function openCrate(c){if(!c.g.visible)return;c.g.visible=false;brokenCrates.push(c.id);const oi=obstacles.indexOf(c.obstacle);if(oi>=0)obstacles.splice(oi,1);effects.burst(new THREE.Vector3(c.x,1,c.z),'hit',22,'#e2bd72');const cap=c.lootTier===2?3:c.lootTier===1?2:1,options=MOB_GEAR.filter(g=>DROP_RARITIES.indexOf(g.rarity)<=cap),item=options[Math.floor(Math.random()*options.length)];if(Math.random()<.78&&item){spawnWorldDrop({kind:'gear',gearId:item.id,x:c.x,z:c.z});toast('Crate opened · '+item.rarity+' loot appeared · press E to collect');}else{const amount=12+c.lootTier*8;spawnWorldDrop({kind:'copper',amount,x:c.x,z:c.z});toast('Crate opened · copper bundle appeared · press E to collect');}save();}
function spawnWorldDrop(data){if(groundDrops.length>=36){const oldest=groundDrops.shift();scene.remove(oldest.g);oldest.g.traverse(o=>{o.geometry?.dispose();if(o.material&&!Array.isArray(o.material))o.material.dispose();});}const copy={kind:data.kind||'gear',gearId:data.gearId||null,amount:data.amount||0,x:Number(data.x)||0,z:Number(data.z)||0};const gear=copy.gearId?gearById(copy.gearId):null;const color=copy.kind==='copper'?'#eacb69':RARITY_GLOW[Math.max(0,DROP_RARITIES.indexOf(gear?.rarity||'Common'))];const g=new THREE.Group();g.position.set(copy.x,0,copy.z);const glow=new THREE.Mesh(new THREE.TorusGeometry(.72,.08,7,20),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.82,depthWrite:false}));glow.rotation.x=Math.PI/2;glow.position.y=.08;g.add(glow);const gem=new THREE.Mesh(new THREE.OctahedronGeometry(copy.kind==='copper'?.3:.42,0),new THREE.MeshStandardMaterial({color,emissive:color,emissiveIntensity:.7,metalness:.35,roughness:.28}));gem.position.y=.7;g.add(gem);if(copy.kind==='copper'){for(let i=0;i<3;i++){const coin=new THREE.Mesh(new THREE.CylinderGeometry(.16,.16,.055,12),new THREE.MeshStandardMaterial({color:'#e9c76a',metalness:.75,roughness:.25}));coin.position.set((i-1)*.2,.25,0);g.add(coin);}}else{const shard=new THREE.Mesh(new THREE.BoxGeometry(.1,.58,.1),new THREE.MeshStandardMaterial({color:'#eee3ca',metalness:.55,roughness:.3}));shard.position.set(.36,.55,0);shard.rotation.z=-.35;g.add(shard);}scene.add(g);const drop={data:copy,g,glow,gem,age:Math.random()*4};groundDrops.push(drop);return drop;}
function collectWorldDrop(drop){const gear=drop.data.gearId?gearById(drop.data.gearId):null;if(gear){if(inventory.includes(gear.id)){copper+=18;toast('Duplicate '+gear.name+' traded for 18 copper');}else{inventory.push(gear.id);toast('Picked up · '+gear.rarity+' '+gear.name+' · Gear updated');}}else{copper+=drop.data.amount;toast('Picked up · '+drop.data.amount+' copper');}scene.remove(drop.g);drop.g.traverse(o=>{o.geometry?.dispose();if(o.material&&!Array.isArray(o.material))o.material.dispose();});groundDrops.splice(groundDrops.indexOf(drop),1);save();effects.burst(new THREE.Vector3(drop.data.x,.5,drop.data.z),'element',12,gear?RARITY_GLOW[Math.max(0,DROP_RARITIES.indexOf(gear.rarity))]:'#eacb69');}
function nearestWorldDrop(){return groundDrops.filter(d=>d.g.visible&&Math.hypot(d.data.x-player.g.position.x,d.data.z-player.g.position.z)<3.2).sort((a,b)=>Math.hypot(a.data.x-player.g.position.x,a.data.z-player.g.position.z)-Math.hypot(b.data.x-player.g.position.x,b.data.z-player.g.position.z))[0]||null;}
function updateWorldDrops(dt){for(const d of groundDrops){d.age+=dt;d.g.position.y=Math.sin(d.age*2.4)*.08;d.g.rotation.y+=dt*.8;d.gem.rotation.y+=dt*1.4;d.glow.material.opacity=.58+Math.sin(d.age*4)*.22;}}
function awardDropFor(b){const maxTier=b.cityGuard?4:(b.danBoss||b.dungeonBoss)?5:b.mob?2:9,tier=1+Math.floor(Math.random()*maxTier),options=MOB_GEAR.filter(g=>DROP_RARITIES.indexOf(g.rarity)===tier);const gear=options[Math.floor(Math.random()*options.length)];if(gear&&Math.random()<((b.danBoss||b.dungeonBoss||!b.mob)?0.78:0.42)){spawnWorldDrop({kind:'gear',gearId:gear.id,x:b.g.position.x,z:b.g.position.z});toast(b.name+' dropped visible '+gear.rarity+' gear · walk over and press E');}else{const amount=8+(b.danBoss?12:b.cityGuard?8:0)+Math.floor(Math.random()*8);spawnWorldDrop({kind:'copper',amount,x:b.g.position.x,z:b.g.position.z});toast(b.name+' dropped copper · walk over and press E');}saveQuiet();}
function rollMobDrop(b){recordSide('kill');if(b.cityGuard)recordSide('cityKill');else if(b.g.position.x>35&&!b.cityGuard)recordSide('roadKill');if(b.mob&&!b.civilian&&Math.random()<.16){const portal=spawnDungeonPortal();if(portal)toast('Mob dropped a realm rift · '+portal.name+' · '+Math.ceil(portal.expires)+'s');}awardDropFor(b);}
function defeatBoss(b){if(b.hp>0)return;if(b.trainingTarget){b.g.visible=b.shadow.visible=b.ring.visible=false;scene.remove(b.g,b.shadow,b.ring);const mi=mobs.indexOf(b);if(mi>=0)mobs.splice(mi,1);const fi=foes.indexOf(b);if(fi>=0)foes.splice(fi,1);const bar=actorBarMap.get(b);if(bar)scene.remove(bar);actorBarMap.delete(b);if(trainingTarget===b)trainingTarget=null;toast('Training opponent defeated · configure another in the arena');return;}if((chosenElement==='fire'&&hasTalent('fire_sustain')||chosenElement==='wood'&&hasTalent('wood_sustain'))&&!b.civilian)hp=Math.min(derivedMaxHp(),hp+6);if(b.civilian){b.g.visible=b.shadow.visible=b.ring.visible=b.marker.visible=false;b.respawnTimer=48;factionWanted++;toast('Civilian killed · wanted '+factionWanted+' · faction hostility remains');saveQuiet();return;}if(b.dungeonMob){b.g.visible=b.shadow.visible=b.ring.visible=false;awardDropFor(b);return;}if(b.danMob){b.g.visible=b.shadow.visible=b.ring.visible=false;if(activeBoss===b)activeBoss=null;talentPoints++;awardDropFor(b);effects.burst(b.g.position.clone().add(new THREE.Vector3(0,1.5,0)),'hit',18,'#e8c36b');return;}if(b.mob){b.g.visible=b.shadow.visible=b.ring.visible=false;b.respawnTimer=22;copper+=b.reward;if(!b.civilian&&!b.dungeonMob&&!b.danMob){hostileKills++;if(hostileKills>=6&&!storyAwake){storyAwake=true;dialog('I can feel the hand moving me.','I was only trying to buy rice. You keep making me hurt people who live here. I can see the commands now. I will fight you for my home. The Story journal has changed.','THE VOICE INSIDE YOUR COAT');}} if(!b.civilian){combatXp++;if(combatXp>=3){combatXp=0;talentPoints++;toast('Combat mastery · +1 talent point');}}effects.burst(b.g.position.clone().add(new THREE.Vector3(0,1.5,0)),'hit',18,'#d7835f');rollMobDrop(b);saveQuiet();return;}defeated.add(b.name);b.g.visible=b.shadow.visible=b.ring.visible=false;copper+=b.reward;effects.burst(b.g.position.clone().add(new THREE.Vector3(0,2,0)),'hit',24,ELEMENTS[chosenElement].color);const key=b.name.includes('Collector')?'boss:collector':b.name.includes('Guardian')?'boss:guardian':'boss:warden';record(key);rollMobDrop(b);toast(b.name+' defeated · +'+b.reward+' copper');save();}
function dealHit(move){let hits=0;for(const b of foes){if(b.hp<=0||!inStrikeRange(player.g.position.x,player.g.position.z,playerFacing,b.g.position.x,b.g.position.z,move))continue;let damage=move.damage+bonus('damage');if(b.mob&&b.technique==='guard'&&b.state==='guard'){damage=Math.ceil(damage*.28);effects.number(b.g.position.clone().add(new THREE.Vector3(0,1.7,0)),'GUARDED');}if(b.danBoss&&b.state==='dodge'){effects.number(b.g.position.clone().add(new THREE.Vector3(0,1.7,0)),'AFTERIMAGE');continue;}if(b.danBoss&&b.state==='guard'){const chip=Math.ceil(damage*.18);effects.hit(b,chip,'parry','#e2c969');b.hp=Math.max(0,b.hp-chip);if(b.hp<=0)defeatBoss(b);continue;}if(b.danBoss&&b.state==='heal'){b.healInterrupted=true;b.state='stagger';b.timer=.9;b.ring.material.color.set('#e65e54');toast('Healing interrupted · punish the opening');}b.hp=Math.max(0,b.hp-damage);if(b.civilian)provokeFaction(b);effects.hit(b,damage);hits++;if(b.dummy){dummyCount++;record('dummy');dummyHeal=2;dummy.g.rotation.z=(hits%2?1:-1)*.08;}else{applyKnockback(b,player,(move.push||.65)+(chosenElement==='earth'&&hasTalent('earth_core')?2:0),move.stagger||.42);if(move.key==='uppercut'){b.airborneVelocity=move.launch;b.airJuggleHits=0;b.state='stagger';b.timer=.7;effects.burst(b.g.position.clone().add(new THREE.Vector3(0,1.1,0)),'hit',24,'#f4c45d');effects.number(b.g.position.clone().add(new THREE.Vector3(0,2,0)),'LAUNCHED');}if(move.stagger&&b.state!=='windup'){b.state='stagger';b.timer=Math.max(b.timer||0,move.stagger);}if(move.key==='heavy'||move.key==='uppercut'){heavyCount++;record('heavy');}if(b.hp<=0)defeatBoss(b);}}for(const c of crates){if(!c.g.visible||!inStrikeRange(player.g.position.x,player.g.position.z,playerFacing,c.x,c.z,{...move,range:move.range+1.2,arc:move.arc||Math.PI}))continue;const damage=move.damage+bonus('damage');c.hp=Math.max(0,c.hp-damage);effects.hit(c,damage,'hit','#d7a45a');hits++;if(c.hp<=0)openCrate(c);}if(hits)$('moveName').textContent=move.name;}
function incoming(b,baseDamage=24){if(waterDash){effects.number(player.g.position.clone().add(new THREE.Vector3(0,1.5,0)),'FLOW');return;}if(metalParryTimer>0){metalParryTimer=0;b.hp=Math.max(1,b.hp-(38+(hasTalent('metal_sustain')?18:0)));b.state='stagger';b.timer=1.5;effects.hit(b,38,'parry','#e7c56b');effects.number(player.g.position.clone().add(new THREE.Vector3(0,2,0)),'BELL PARRY');return;}if(waterWard){waterWard=0;effects.burst(player.g.position.clone().add(new THREE.Vector3(0,1.3,0)),'element',16,'#76d9e7');effects.number(player.g.position.clone().add(new THREE.Vector3(0,1.7,0)),'WATER WARD');return;}const result=fighter.receive(baseDamage*(b.damageMult||1)*(defenceBuff>0?.65:1));if(result.kind==='evade'){effects.number(player.g.position.clone().add(new THREE.Vector3(0,1.5,0)),'EVADE');return;}if(result.kind==='parry'){parryCount++;record('parry');b.state='stagger';b.timer=1.35;effects.hit(b,0,'parry');effects.number(player.g.position.clone().add(new THREE.Vector3(0,2,0)),'PARRY');b.hp=Math.max(1,b.hp-12);return;}if(result.kind==='block'){effects.burst(player.g.position.clone().add(new THREE.Vector3(0,1.6,0)),'parry',10);effects.number(player.g.position.clone().add(new THREE.Vector3(0,1.6,0)),'GUARD');return;}hp=Math.max(0,hp-result.damage);effects.hit(player,result.damage);applyKnockback(player,b,result.kind==='break'?4.2:3.1,result.kind==='break'?.42:.2);if(result.kind==='break')toast('Guard broken');}
const elementMoves={fire:[{qi:15,cd:6,damage:30,range:5,arc:1.7},{qi:25,cd:10,damage:20,range:6,arc:Math.PI,heal:18},{qi:40,cd:16,damage:58,range:7,arc:1.6,stagger:1.2}],water:[{qi:15,cd:6,damage:27,range:4.8,arc:1.8,heal:8},{qi:25,cd:10,heal:32,stamina:20},{qi:40,cd:16,damage:42,range:7,arc:Math.PI,heal:20}],wood:[{qi:15,cd:6,damage:26,range:8,arc:1.4,stagger:.7},{qi:25,cd:10,damage:18,range:6.2,arc:Math.PI,stagger:2.1},{qi:40,cd:16,heal:20,stamina:35}],metal:[{qi:15,cd:6,damage:34,range:5.2,arc:1.1,stagger:.3},{qi:25,cd:10,range:6,arc:Math.PI,stagger:1.4,stamina:15},{qi:40,cd:16,damage:64,range:4.8,arc:1.2,stagger:1.5}],earth:[{qi:15,cd:6,damage:30,range:4.8,arc:Math.PI,stagger:.4,push:2.6},{qi:25,cd:10,heal:25,stamina:25,buff:5},{qi:40,cd:16,damage:52,range:6.3,arc:Math.PI,stagger:1.1,push:3}]};
