function spawnFirebolt(target,damage){const origin=player.g.position.clone().add(new THREE.Vector3(0,1.35,0)),dir=new THREE.Vector3(Math.sin(playerFacing),0,Math.cos(playerFacing));const dest=target?target.g.position.clone().add(new THREE.Vector3(0,1.3,0)):origin.clone().add(dir.multiplyScalar(14));const mesh=new THREE.Group(),core=new THREE.Mesh(new THREE.IcosahedronGeometry(.24,1),new THREE.MeshBasicMaterial({color:'#fff0a0'})),flame=new THREE.Mesh(new THREE.IcosahedronGeometry(.4,1),new THREE.MeshBasicMaterial({color:'#ff6b28',transparent:true,opacity:.8}));mesh.add(flame,core);mesh.position.copy(origin);scene.add(mesh);projectiles.push({mesh,target,origin,dest,age:0,duration:.48,damage});}
function spawnEnemyShot(b,angle=null){const origin=b.g.position.clone().add(new THREE.Vector3(Math.sin(b.g.rotation.y)*.65,1.3,Math.cos(b.g.rotation.y)*.65)),mesh=new THREE.Mesh(new THREE.IcosahedronGeometry(b.dungeonBoss?.28:.23,1),new THREE.MeshBasicMaterial({color:b.dungeonBoss?'#cf88ed':'#ff9a58'}));mesh.position.copy(origin);scene.add(mesh);effects.burst(origin,'element',5,b.dungeonBoss?'#cf88ed':'#ff9a58');const dest=angle===null?player.g.position.clone().add(new THREE.Vector3(0,1.1,0)):b.g.position.clone().add(new THREE.Vector3(Math.sin(angle)*20,1.05,Math.cos(angle)*20));enemyProjectiles.push({mesh,source:b,origin,dest,age:0,duration:.72});}
