 if(chosenElement==='wood'&&(index===0||index===1)){const targets=foes.filter(b=>b.hp>0&&inStrikeRange(player.g.position.x,player.g.position.z,playerFacing,b.g.position.x,b.g.position.z,{...move,key:'element'}));for(const b of targets){const dmg=move.damage+bonus('damage')+elementDamageBonus();b.hp=Math.max(0,b.hp-dmg);if(b.civilian)provokeFaction(b);effects.hit(b,dmg,'element',color);vines.push({target:b,age:0,duration:.85});if(move.stagger){b.state='stagger';b.timer=Math.max(b.timer,move.stagger+(chosenElement==='wood'&&hasTalent('wood_core')?.35:0));}if(b.dummy){dummyCount++;record('dummy');dummyHeal=2;}else if(b.hp<=0)defeatBoss(b);}landed=targets.length>0;effects.burst(player.g.position.clone().add(new THREE.Vector3(0,1,0)),'element',14,color);$('moveName').textContent=index===0?'Briar Snare':'Thorn Cage';toast(index===0?'Briar Snare · vines seize the target':'Thorn Cage · roots lash in a circle');saveQuiet();return;}
 if(chosenElement==='metal'&&index===1){metalParryTimer=1.4+(hasTalent('metal_core')?.4:0);fighter.stamina=Math.min(100,fighter.stamina+(move.stamina||15));effects.burst(player.g.position.clone().add(new THREE.Vector3(0,1.1,0)),'element',22,color);$('moveName').textContent='Bell Parry';toast('Bell Parry · reflect the next hit');saveQuiet();return;}
 if(chosenElement==='water'&&index===1){hp=Math.min(derivedMaxHp(),hp+move.heal+(hasTalent('water_sustain')?12:0));fighter.stamina=Math.min(100,fighter.stamina+(move.stamina||0));waterWard=1;effects.burst(player.g.position.clone().add(new THREE.Vector3(0,1,0)),'element',20,color);$('moveName').textContent='Still Pool';toast('Still Pool · restored, next hit warded');saveQuiet();return;}
 if(move.heal){hp=Math.min(derivedMaxHp(),hp+move.heal+(chosenElement==='water'&&hasTalent('water_sustain')?12:0));if(move.stamina)fighter.stamina=Math.min(100,fighter.stamina+move.stamina);if(move.buff)defenceBuff=move.buff;effects.burst(player.g.position.clone().add(new THREE.Vector3(0,1,0)),'element',18,color);}
 if(move.damage){sendDuelAttack('element');for(const b of foes){if(b.hp<=0||!inStrikeRange(player.g.position.x,player.g.position.z,playerFacing,b.g.position.x,b.g.position.z,{...move,key:'element'}))continue;const dmg=move.damage+bonus('damage')+elementDamageBonus();b.hp=Math.max(0,b.hp-dmg);if(b.civilian)provokeFaction(b);effects.hit(b,dmg,'element',color);landed=true;if(move.stagger){b.state='stagger';b.timer=Math.max(b.timer,move.stagger);}if(move.push){applyKnockback(b,player,move.push);}if(chosenElement==='fire'){b.burnTime=3;b.burnTick=.0;}if(b.dummy){dummyCount++;record('dummy');dummyHeal=2;}else if(b.hp<=0)defeatBoss(b);}}
